// Regenerates docs/species-sources.md from the species catalog and verification ledger.
import { readFileSync, writeFileSync } from 'node:fs';

const read = (p) => JSON.parse(readFileSync(new URL(p, import.meta.url), 'utf8'));
const species = [...read('../src/data/species/animals.json'), ...read('../src/data/species/plants.json')];
const ledger = read('../src/data/species/verification.json');

const verified = species.filter((s) => ledger[s.id]?.taxonomy === 'verified');
const lines = [
  '# Species sources and verification',
  '',
  '_Generated by `node scripts/species-report.mjs` — do not edit by hand._',
  '',
  `The catalog holds **${species.length} real species**. Every record carries a verification state that the game shows on the species page.`,
  '',
  `- **Verified** (${verified.length}): scientific name, classification and (where one is claimed) the IUCN Red List category were checked against the sources listed.`,
  `- **Unverified** (${species.length - verified.length}): compiled from general reference knowledge and not yet checked against a cited source. The game labels these entries as unverified.`,
  '',
  'Descriptive text (behaviour, adaptations, facts, sizes) was written from general reference knowledge for all species and has not been individually sourced; treat it as educational summary, not as a citable reference.',
  '',
  '| Species | Scientific name | Family | IUCN claimed | Classification | Status |',
  '|---|---|---|---|---|---|',
];
for (const s of species) {
  const v = ledger[s.id];
  lines.push(
    `| ${s.commonNameEn} / ${s.commonNameVi} | *${s.scientificName}* | ${s.family} | ${s.conservationStatus ?? '—'} | ${v?.taxonomy === 'verified' ? 'verified' : 'unverified'} | ${
      !s.conservationStatus ? 'not claimed' : v?.conservation === 'verified' ? 'verified' : 'unverified'
    } |`,
  );
}
lines.push('', '## Sources for verified records', '');
for (const s of verified) {
  const v = ledger[s.id];
  lines.push(`### ${s.commonNameEn} (*${s.scientificName}*)`, '');
  for (const src of v.sources) lines.push(`- [${src.label}](${src.url})`);
  if (v.note) lines.push('', v.note);
  lines.push('');
}
lines.push(
  '## How to verify the rest',
  '',
  'For each unverified species, check the accepted name and classification (GBIF Backbone, Catalogue of Life, Plants of the World Online, FishBase, The Reptile Database, ASM Mammal Diversity Database, BirdLife DataZone) and the Red List category (iucnredlist.org), then add an entry to `src/data/species/verification.json` with the URLs. The unit test `species.test.ts` refuses a record marked verified without a source.',
  '',
);
writeFileSync(new URL('../docs/species-sources.md', import.meta.url), lines.join('\n'));
console.log(`species: ${species.length}, verified: ${verified.length}`);
